def find_target_sum_ways(nums, target):
    T = sum(nums)
    if abs(target) > T:
        return 0
    n = len(nums)
    dp = [[0] * (2 * T + 1) for _ in range(n + 1)]
    dp[0][T] = 1                       # column s + T holds sum s
    for i in range(1, n + 1):
        x = nums[i - 1]
        for s in range(-T, T + 1):
            if s - x >= -T:
                dp[i][s + T] += dp[i - 1][s - x + T]
            if s + x <= T:
                dp[i][s + T] += dp[i - 1][s + x + T]
    return dp[n][target + T]

def find_target_sum_ways(nums, target):
    T = sum(nums)
    if abs(target) > T:
        return 0
    prev = [0] * (2 * T + 1)
    prev[T] = 1
    for x in nums:
        cur = [0] * (2 * T + 1)
        for s in range(-T, T + 1):
            if s - x >= -T:
                cur[s + T] += prev[s - x + T]
            if s + x <= T:
                cur[s + T] += prev[s + x + T]
        prev = cur
    return prev[target + T]

def find_target_sum_ways(nums, target):
    T = sum(nums)
    if abs(target) > T or (T + target) % 2:
        return 0
    P = (T + target) // 2
    ways = [1] + [0] * P
    for x in nums:
        for s in range(P, x - 1, -1):     # downwards: each number once
            ways[s] += ways[s - x]
    return ways[P]
